const role=new URLSearchParams(location.search).get('role')||'admin';
const user={id:'sample-user',email:role==='admin'?'nick@example.com':'caro@example.com',app_metadata:{role,client:'suitecollection'},user_metadata:{name:role==='admin'?'Nick':'Caro'}};
const now=new Date().toISOString();
let ideas=[{id:'existing-1',client:'suitecollection',idea_date:'2026-10-14',description:'Dog park opening at Liven Beach Road',notes:'Pending photos from Caro',created_by:'sample-user',author_label:'Caro',author_role:'client',created_at:now,updated_at:now,archived_at:null},{id:'existing-2',client:'suitecollection',idea_date:'2026-10-20',description:'Community talking heads video',notes:'Interview two residents',created_by:'other-user',author_label:'Nick',author_role:'admin',created_at:now,updated_at:now,archived_at:null}];
const posts=[{id:'sample-approved',client:'suitecollection',slot:1,review_status:'approved',caption:'Approved sample post',thumbnail_url:'/assets/filled.png',media_urls:['/assets/filled.png','/assets/empty.png'],facebook_media_urls:['/assets/empty.png'],platform:'instagram'},{id:'sample-new',client:'suitecollection',slot:2,review_status:null,caption:'New sample post',thumbnail_url:'/assets/filled.png',media_urls:['/assets/filled.png','/assets/empty.png'],facebook_media_urls:['/assets/empty.png'],platform:'instagram'}];
let dateHeaders=[];
const events=[];function log(v){events.push(v);document.body.dataset.calendarEvents=JSON.stringify(events);}
class Query{constructor(table){this.table=table;this.filters=[];this.action='select';}select(){return this;}eq(k,v){this.filters.push(x=>x[k]===v);return this;}is(k,v){return this.eq(k,v);}gte(k,v){this.filters.push(x=>x[k]>=v);return this;}lt(k,v){this.filters.push(x=>x[k]<v);return this;}order(){return this;}insert(p){this.action='insert';this.payload=p;return this;}update(p){this.action='update';this.payload=p;return this;}single(){this.one=true;return this;}then(resolve){if(this.table==='calendar_date_headers'){let rows=dateHeaders.filter(x=>this.filters.every(f=>f(x)));if(this.action==='insert'){const row={...this.payload,updated_at:new Date().toISOString()};dateHeaders.push(row);rows=[row];log({action:'heading-insert',payload:this.payload});}if(this.action==='update'){rows.forEach(x=>Object.assign(x,this.payload,{updated_at:new Date().toISOString()}));log({action:'heading-update',payload:this.payload});}return Promise.resolve({data:this.one?rows[0]:rows,error:null}).then(resolve);}if(this.table==='posts')return Promise.resolve({data:posts.filter(x=>this.filters.every(f=>f(x))),error:null}).then(resolve);if(this.table!=='calendar_ideas')return Promise.resolve({data:[],error:null}).then(resolve);let rows=ideas.filter(x=>this.filters.every(f=>f(x)));if(this.action==='insert'){const row={...this.payload,created_by:user.id,author_label:user.user_metadata.name,author_role:role,created_at:new Date().toISOString(),updated_at:new Date().toISOString(),archived_at:null};ideas.push(row);rows=[row];log({action:'insert',payload:this.payload});}if(this.action==='update'){if(rows.length&&role==='client'&&rows[0].created_by!==user.id)return Promise.resolve({data:null,error:{code:'42501'}}).then(resolve);rows.forEach(x=>Object.assign(x,this.payload,{updated_at:new Date().toISOString()}));log({action:'update',payload:this.payload});}return Promise.resolve({data:this.one?rows[0]:rows,error:null}).then(resolve);}}
export const supabase={auth:{refreshSession:async()=>({data:{session:{user}}}),signOut:async()=>{}},from:t=>new Query(t)};
